float hash21(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
vec2 hash22(vec2 p){return vec2(hash21(p),hash21(p+31.7));}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
    vec2 uv=fragCoord/iResolution.xy;
    vec2 st=uv*6.0;
    vec2 ip=floor(st),fp=fract(st);
    float d0=1e9,d1=1e9;
    for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){
        vec2 nb=vec2(float(x),float(y));
        vec2 pt=0.5+0.45*sin(iTime*0.25+6.2831*hash22(ip+nb));
        float d=length(nb+pt-fp);
        if(d<d0){d1=d0;d0=d;}else if(d<d1){d1=d;}
    }
    float edge=d1-d0;
    float cool=clamp(iTime*0.38,0.0,1.0);
    float crustW=smoothstep(0.0,0.28,edge);
    vec3 molten=vec3(1.0,0.38,0.04);
    vec3 crust=vec3(0.07,0.05,0.04);
    vec3 cell=mix(molten,crust,crustW*cool);
    float glow=1.0-smoothstep(0.0,0.12,edge);
    float crackHeat=1.0-cool*0.7;
    vec3 crack=mix(vec3(1.0,0.55,0.08),vec3(0.5,0.08,0.0),cool)*crackHeat;
    vec3 col=mix(cell,crack,glow);
    fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

float hash21(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);float a=hash21(i),b=hash21(i+vec2(1,0)),c=hash21(i+vec2(0,1)),d=hash21(i+vec2(1,1));return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);}
float fbm(vec2 p){float v=0.0,a=0.5;for(int i=0;i<5;i++){v+=a*noise(p);p*=2.0;a*=0.5;}return v;}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
    vec2 uv=fragCoord/iResolution.xy;
    vec2 st=uv*3.0;
    float t=iTime;
    vec2 q=vec2(fbm(st+t*0.09),fbm(st+vec2(5.2,1.3)+t*0.07));
    vec2 r=vec2(fbm(st+2.0*q+vec2(1.7,9.2)),fbm(st+2.0*q+vec2(8.3,2.8)));
    float f=fbm(st+2.5*r);
    // ridge: narrow bright band near threshold
    float cool=clamp(t*0.3,0.0,1.0);
    float thresh=0.52;
    float ridge=1.0-abs(f-thresh)*18.0;
    ridge=clamp(ridge,0.0,1.0)*smoothstep(0.0,0.4,cool);
    vec3 molten=vec3(1.0,0.45+f*0.3,0.05);
    vec3 crust=vec3(0.09-f*0.04,0.06,0.04);
    vec3 col=mix(molten,crust,cool*(1.0-ridge));
    col=mix(col,vec3(1.0,0.5,0.06),ridge);
    fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

