float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);float a=hash21(i),b=hash21(i+vec2(1,0)),c=hash21(i+vec2(0,1)),d=hash21(i+vec2(1,1));return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
    vec2 uv=(fragCoord-0.5*iResolution.xy)/iResolution.y;
    float r=length(uv);
    float a=atan(uv.y,uv.x);
    float cool=clamp(iTime*0.32,0.0,1.0);
    // crust front: annular ring expanding from outside in
    float crustFront=0.85-cool*0.78;
    float isCrust=smoothstep(crustFront,crustFront+0.05,r);
    // radial crack lines: noise in angle domain
    float crackN=noise(vec2(a*4.0/3.14159+5.0,r*8.0+iTime*0.1));
    float crack=(1.0-smoothstep(0.0,0.08,abs(crackN-0.5)))*isCrust*smoothstep(0.0,0.3,isCrust);
    // ring edge glow
    float frontGlow=1.0-smoothstep(0.0,0.06,abs(r-crustFront));
    vec3 molten=mix(vec3(1.0,0.65,0.05),vec3(1.0,0.2,0.0),clamp(r*1.2,0.0,1.0));
    vec3 crust=vec3(0.08,0.06,0.05)*mix(1.0,0.5,crackN);
    vec3 col=mix(molten,crust,isCrust*(1.0-crack));
    col=mix(col,vec3(1.0,0.5,0.05),crack+frontGlow*(1.0-isCrust*0.5));
    fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

float hash21(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
float noise(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);float a=hash21(i),b=hash21(i+vec2(1,0)),c=hash21(i+vec2(0,1)),d=hash21(i+vec2(1,1));return mix(mix(a,b,f.x),mix(c,d,f.x),f.y);}
float ridge(vec2 p){float v=0.0,a=0.5,s=1.0;for(int i=0;i<6;i++){float n=1.0-abs(noise(p)*2.0-1.0);v+=n*n*a;p*=2.1;a*=0.48;}return v;}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
    vec2 uv=fragCoord/iResolution.xy;
    float t=iTime;
    vec2 st=uv*4.0+vec2(t*0.04,0.0);
    float rn=ridge(st);
    // crack: narrow band near ridge peaks
    float crackLine=smoothstep(0.62,0.75,rn);
    // base surface: slow noise for crust texture
    float surf=noise(uv*8.0+t*0.05)*0.3+noise(uv*16.0)*0.1;
    float cool=clamp(t*0.33,0.0,1.0);
    // crust grows over surface, interrupted by cracks
    float crustVal=clamp(cool-surf*0.3,0.0,1.0)*(1.0-crackLine);
    vec3 molten=vec3(1.0,0.35+surf,0.03);
    vec3 crust=vec3(0.1+surf*0.15,0.08,0.06);
    vec3 crack=vec3(1.0,0.5+0.1*sin(t*4.0+rn*10.0),0.04);
    vec3 col=mix(mix(molten,crust,crustVal),crack,crackLine);
    fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

float hash21(vec2 p){p=fract(p*vec2(123.34,456.21));p+=dot(p,p+45.32);return fract(p.x*p.y);}
vec2 hash22(vec2 p){return fract(p*mat2(127.1,311.7,269.5,183.3));}

void mainImage(out vec4 fragColor,in vec2 fragCoord){
    vec2 uv=fragCoord/iResolution.xy;
    vec2 st=uv*7.0;
    vec2 ip=floor(st),fp=fract(st);
    float F1=1e9,F2=1e9;
    vec2 mg=vec2(0.0);
    for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){
        vec2 nb=vec2(float(x),float(y));
        vec2 rp=hash22(ip+nb);
        rp=0.5+0.45*sin(6.2831*rp+iTime*0.2);
        float d=length(nb+rp-fp);
        if(d<F1){F2=F1;F1=d;mg=ip+nb;}else if(d<F2){F2=d;}
    }
    float cell=F2-F1;
    float interior=F1;
    // smooth crack width
    float crack=1.0-smoothstep(0.0,0.1,cell);
    float cool=clamp(iTime*0.35,0.0,1.0);
    // per-cell cooling offset using cell id hash
    float cellPhase=hash21(mg);
    float cellCool=clamp((cool-cellPhase*0.4)*2.5,0.0,1.0);
    vec3 molten=mix(vec3(1.0,0.55,0.02),vec3(0.9,0.25,0.0),interior*1.5);
    vec3 crust=mix(vec3(0.12,0.08,0.06),vec3(0.04,0.03,0.02),interior);
    vec3 crackCol=vec3(1.0,0.45+0.1*sin(iTime*3.0),0.03)*(1.0-cool*0.6);
    vec3 col=mix(mix(molten,crust,cellCool),crackCol,crack);
    fragColor=vec4(clamp(col,0.0,1.0),1.0);
}

